def shapes(grid):
    """The connected nonzero blocks of the grid, each cropped to its bounding box."""
    seen=set(); res=[]
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] and (i,j) not in seen:
                stack=[(i,j)]; comp=[]
                while stack:
                    x,y=stack.pop()
                    if (x,y) in seen or not (0<=x<len(grid) and 0<=y<len(grid[0])) or grid[x][y]==0: continue
                    seen.add((x,y)); comp.append((x,y))
                    stack += [(x+1,y),(x-1,y),(x,y+1),(x,y-1)]
                xs=[p[0] for p in comp]; ys=[p[1] for p in comp]
                res.append([[grid[x][y] for y in range(min(ys),max(ys)+1)] for x in range(min(xs),max(xs)+1)])
    return res
